1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { apiFetch, ApiError } from '../lib/api';
4	  import { sessionStore } from '../stores/session.svelte';
5	
6	  type LoadState = 'idle' | 'loading' | 'done' | 'error';
7	
8	  interface OpportunityItem {
9	    title: string;
10	    type: 'billable' | 'internal';
11	    details: string;
12	  }
13	
14	  let state = $state<LoadState>('idle');
15	  let opportunities = $state<OpportunityItem[]>([]);
16	  let errorMessage = $state<string | null>(null);
17	
18	  const sessionHeaders = (): Record<string, string> =>
19	    sessionStore.sessionId ? { 'X-Autom9-Session': sessionStore.sessionId } : {};
20	
21	  async function loadOpenWork(): Promise<void> {
22	    state = 'loading';
23	    try {
24	      const response = await apiFetch<{ data: OpportunityItem[] }>('/api/data/open-work', {
25	        headers: sessionHeaders(),
26	      });
27	      opportunities = response.data;
28	      state = 'done';
29	    } catch (err) {
30	      const msg =
31	        err instanceof ApiError
32	          ? err.message
33	          : err instanceof Error
34	            ? err.message
35	            : 'Could not load open work opportunities';
36	      errorMessage = msg;
37	      state = 'error';
38	    }
39	  }
40	
41	  onMount(() => {
42	    loadOpenWork();
43	  });
44	</script>
45	
46	<div class="open-work-panel">
47	  <section class="panel-section">
48	    <h3>Open Work Opportunities</h3>
49	    {#if state === 'loading'}
50	      <p class="loading">Loading…</p>
51	    {:else if state === 'error'}
52	      <p class="error">{errorMessage}</p>
53	    {:else if opportunities.length === 0}
54	      <p class="empty">No open work opportunities available</p>
55	    {:else}
56	      <ul>
57	        {#each opportunities as opp}
58	          <li class="opportunity">
59	            <span class="badge badge-{opp.type}">{opp.type === 'billable' ? 'Billable' : 'Internal'}</span>
60	            <span class="title">{opp.title}</span>
61	          </li>
62	        {/each}
63	      </ul>
64	    {/if}
65	  </section>
66	</div>
67	
68	<style>
69	  .open-work-panel {
70	    font-family: sans-serif;
71	    padding: 0.75rem;
72	  }
73	  .panel-section {
74	    margin-bottom: 1.25rem;
75	  }
76	  h3 {
77	    font-size: 0.875rem;
78	    font-weight: 600;
79	    margin: 0 0 0.5rem;
80	    text-transform: uppercase;
81	    letter-spacing: 0.05em;
82	    color: #444;
83	  }
84	  .loading { color: #666; font-style: italic; }
85	  .error { color: #c00; }
86	  .empty { color: #888; }
87	  ul {
88	    margin: 0;
89	    padding: 0;
90	    list-style: none;
91	  }
92	  .opportunity {
93	    display: flex;
94	    align-items: center;
95	    gap: 0.5rem;
96	    padding: 0.3rem 0;
97	    font-size: 0.875rem;
98	    border-bottom: 1px solid #f0f0f0;
99	  }
100	  .opportunity:last-child {
101	    border-bottom: none;
102	  }
103	  .badge {
104	    font-size: 0.7rem;
105	    font-weight: 600;
106	    padding: 0.1rem 0.4rem;
107	    border-radius: 3px;
108	    white-space: nowrap;
109	    text-transform: uppercase;
110	    letter-spacing: 0.03em;
111	  }
112	  .badge-billable {
113	    background: #e6f4ea;
114	    color: #137333;
115	  }
116	  .badge-internal {
117	    background: #e8eaf6;
118	    color: #3949ab;
119	  }
120	  .title {
121	    color: #222;
122	  }
123	</style>
